int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    int *A = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) scanf("%d", &A[i]);

    /* Special case: after 0 uses, you stay where you are.
       To be at town 1 from every town is impossible unless N=1. */
    if (K == 0) {
        printf("%d\n", (N == 1 ? 0 : -1));
        free(A);
        return 0;
    }

    /* Build reverse graph excluding town 1:
       for edge i -> A[i], if A[i] != 1 then add i as child of A[i].
       Nodes whose teleporter points to 1 are roots of reverse trees. */
    int *head = (int *)malloc((N + 1) * sizeof(int));
    int *to = (int *)malloc((N + 1) * sizeof(int));
    int *next = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 2; i <= N; i++) {
        if (A[i] != 1) {
            to[ecnt] = i;
            next[ecnt] = head[A[i]];
            head[A[i]] = ecnt++;
        }
    }

    /* First, town 1 must reach itself after K steps, so A[1] must be 1. */
    int ans = 0;
    if (A[1] != 1) ans++;

    /* Iterative DFS postorder on each reverse tree rooted at nodes with A[i]=1. */
    int *stack_v = (int *)malloc((N + 1) * sizeof(int));
    int *stack_p = (int *)malloc((N + 1) * sizeof(int));
    int *stack_d = (int *)malloc((N + 1) * sizeof(int));
    int *order_v = (int *)malloc((N + 1) * sizeof(int));
    int *order_p = (int *)malloc((N + 1) * sizeof(int));
    int *order_d = (int *)malloc((N + 1) * sizeof(int));
    int *best = (int *)malloc((N + 1) * sizeof(int));

    for (int r = 2; r <= N; r++) {
        if (A[r] != 1) continue;

        int top = 0, ord = 0;
        stack_v[top] = r;
        stack_p[top] = 0;
        stack_d[top] = 1;
        top++;

        while (top) {
            top--;
            int v = stack_v[top];
            int p = stack_p[top];
            int d = stack_d[top];
            order_v[ord] = v;
            order_p[ord] = p;
            order_d[ord] = d;
            ord++;

            for (int e = head[v]; e != -1; e = next[e]) {
                int u = to[e];
                if (u == p) continue;
                stack_v[top] = u;
                stack_p[top] = v;
                stack_d[top] = d + 1;
                top++;
            }
        }

        for (int i = ord - 1; i >= 0; i--) {
            int v = order_v[i];
            int p = order_p[i];
            int d = order_d[i];

            int mx = d;
            for (int e = head[v]; e != -1; e = next[e]) {
                int u = to[e];
                if (u == p) continue;
                if (best[u] > mx) mx = best[u];
            }

            /* Greedy cut:
               if deepest remaining node in this subtree is at distance K from capital
               and v is not directly under capital, change v's teleporter to 1. */
            if (mx - d + 1 == K && p != 0) {
                ans++;
                best[v] = 0; /* this subtree is fixed by redirecting v to 1 */
            } else {
                best[v] = mx;
            }
        }
    }

    printf("%d\n", ans);

    free(A);
    free(head);
    free(to);
    free(next);
    free(stack_v);
    free(stack_p);
    free(stack_d);
    free(order_v);
    free(order_p);
    free(order_d);
    free(best);
    return 0;
}

