public class Main {
    static int N, K;
    static int[] a;
    static ArrayList<Integer>[] rev;
    static long ans = 0;

    static int[] parent, order, dp;
    static boolean[] vis;

    static void solveFromRoot() {
        parent = new int[N + 1];
        order = new int[N];
        int sz = 0;

        int[] stack = new int[N];
        int top = 0;
        stack[top++] = 1;
        parent[1] = -1;
        vis = new boolean[N + 1];
        vis[1] = true;

        while (top > 0) {
            int u = stack[--top];
            order[sz++] = u;
            for (int v : rev[u]) {
                if (!vis[v]) {
                    vis[v] = true;
                    parent[v] = u;
                    stack[top++] = v;
                }
            }
        }

        dp = new int[N + 1];
        for (int idx = sz - 1; idx >= 0; idx--) {
            int u = order[idx];
            int best = 0;
            for (int v : rev[u]) {
                if (!vis[v] || parent[v] != u) continue;
                int d = dp[v] + 1;
                if (d == K && u != 1) {
                    ans++;
                } else {
                    if (d > best) best = d;
                }
            }
            dp[u] = best;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();
        K = fs.nextInt();
        a = new int[N + 1];
        rev = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) rev[i] = new ArrayList<>();
        for (int i = 1; i <= N; i++) {
            a[i] = fs.nextInt();
        }

        if (a[1] != 1) {
            ans++;
            a[1] = 1;
        }

        for (int i = 1; i <= N; i++) {
            rev[a[i]].add(i);
        }

        solveFromRoot();

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

