int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long K;
    cin >> N >> K;

    vector<int> a(N + 1);
    vector<vector<int>> rev(N + 1);
    for (int i = 1; i <= N; i++) {
        cin >> a[i];
        rev[a[i]].push_back(i);
    }

    // Distance from town 1 in the reverse graph:
    // dist[v] = minimum x such that after x teleports from v, we reach 1.
    vector<long long> dist(N + 1, -1);
    queue<int> q;
    dist[1] = 0;
    q.push(1);

    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int u : rev[v]) {
            if (dist[u] == -1) {
                dist[u] = dist[v] + 1;
                q.push(u);
            }
        }
    }

    long long ans = 0;

    // Town 1 itself must satisfy f^K(1) = 1, so 1 must be in a cycle whose length divides K.
    // Since every town must reach 1 after exactly K steps, the only possible cycle containing 1
    // is a self-loop at 1. Thus if a[1] != 1, we must change it.
    if (a[1] != 1) ans++;

    // For every other town:
    // If dist[v] == -1, it is not in the reverse tree of 1, so it can never reach 1 -> must be changed.
    // If dist[v] > K, then even along the best route it takes too long -> must be changed.
    // If dist[v] <= K, then we can stay at 1 for the remaining steps (requiring 1->1),
    // so no change is needed for this town.
    for (int v = 2; v <= N; v++) {
        if (dist[v] == -1 || dist[v] > K) ans++;
    }

    cout << ans << '\n';
    return 0;
}
